pub struct Solution;

impl Solution {
    pub fn my_pow(x: f64, n: i32) -> f64 {
        let mut x = x;
        let mut n_long = n as i64;
        if n_long < 0 {
            x = 1.0 / x;
            n_long = -n_long;
        }

        let mut ans = 1.0;
        let mut current_product = x;
        let mut i = n_long;
        while i > 0 {
            if i % 2 == 1 {
                ans *= current_product;
            }
            current_product *= current_product;
            i /= 2;
        }
        ans
    }
}

